<template>
  <div class="image-decorator" ref="image-area" id="image_area">
    <div id="screenshot_container">
      <img
        @load="prepareImageData"
        id="screenshot2"
        ref="screenshot2"
        class="original-image"
        :src="url"
        alt="Original Image"
        v-if="url"
        :width="width"
      />
      <div
        class="select-areas--overlay"
        :style="{
          opacity: opacityOverlay,
          position: 'absolute',
          width: originImgSize.w + 'px',
          height: originImgSize.h + 'px',
          display: 'block',
        }"
      ></div>

      <div
        id="draw"
        :style="{
          'background-color': 'rgb(0, 0, 0)',
          opacity: 0,
          position: 'absolute',
          width: originImgSize.w + 'px',
          height: originImgSize.h + 'px',
        }"
        @mousedown="mouseDown"
        @mousemove="mouseMove"
      ></div>

      <div v-for="(item, index) in areas" :key="item.id">
        <div
          @mousedown.stop.prevent="startMove(item, $event)"
          @mousemove="doMove(item, $event)"
        >
          <div
            class="select-areas--outline"
            :style="{
              opacity: opacityOutline,
              position: 'absolute',
              cursor: 'cross',
              width: geStamptDimension(item.width) + 4 + 'px',
              height: geStamptDimension(item.height) + 4 + 'px',
              left: areaDisplayPosX(item) - 2 + 'px',
              top: areaDisplayPosY(item) - 2 + 'px',
              'z-index': item.z,
            }"
          ></div>
          <div
            :id="'annotation_item_' + item.id"
            class="select-areas--background_area"
            @dblclick="itemClicked(index, item)"
            :style="{
              background: `#fff url('${url}') -${areaDisplayPosX(item)}px -${item.y}px / ${originImgSize.w}px ${originImgSize.h}px no-repeat`,
              position: 'absolute',
              cursor: 'grab',
              width: geStamptDimension(item.width) + 'px',
              height: geStamptDimension(item.height) + 'px',
              left: areaDisplayPosX(item) + 'px',
              top: areaDisplayPosY(item) + 'px',
              color: item.font_color,
              fontSize: item.font_size + 'pt',
              fontFamily: item.font_style,
              zIndex: item.z + 2,
            }"
            :class="
              (item.italic ? ' text-italic ' : '') +
              (item.bold ? ' text-bold ' : '')
            "
            @click="changeResizable(item.id)"
          >
            <p
              class="q-ma-none"
              v-for="(val, idx) in textLines(item.text)"
              :key="idx"
            >
              {{ val }}
            </p>
          </div>
          <div
            class="edit-area row back-white"
            v-if="enableEditing"
            :style="{
              display: 'edit',
              left: calculateLeftForEditArea(item) + 'px',
              top: areaDisplayLowerPosY(item) + 10 + 'px',
              'z-index': item.z + 2,
            }"
          >
            <template v-if="item.editable">
              <q-btn
                flat
                @click="itemClicked(index, item)"
                :disable="item.processing"
              >
                <Icon icon="mdi:pencil" width="20" height="20" />
              </q-btn>
              <q-separator vertical class="q-mx-sm" />
            </template>

            <template v-if="item.type === 'normal' || item.annot_id == null">
              <q-btn
                flat
                @click="saveAnnotation(index, item)"
                :disable="item.processing"
              >
                <Icon icon="mdi:content-save" width="20" height="20" />
              </q-btn>

              <q-separator vertical class="q-mx-sm" />
            </template>

            <q-btn
              flat
              @click="deleteAnnotation(index, item)"
              :disable="item.processing"
            >
              <Icon icon="mdi:delete" width="20" height="20" />
            </q-btn>
          </div>

          <!-- resize handler -->
          <Resizable
            v-if="item.resizable && enableEditing"
            :item="item"
            :posImg="posImg"
            :pos-correction="posCorrection"
            @startDrag="startDrag"
            @doDrag="doDrag"
          />
        </div>
      </div>
    </div>
    <div class="c-crop--hide_main">
      <img id="c-crop--hide_img" :src="url" alt="" :width="width" />
    </div>
  </div>

  <q-dialog
    v-model="show_annotation_popup"
    @keydown.esc="show_annotation_popup = false"
  >
    <q-card style="width: 720px">
      <q-toolbar class="text-white secondary-toolbar">
        <q-toolbar-title
          ><span class="text-weight-bold">{{
            $t('new_annotation')
          }}</span>
        </q-toolbar-title>
        <q-btn flat round dense icon="close" @click="cancelEditorChange()" />
      </q-toolbar>
      <div class="row q-pa-sm full-width">
        <div
          class="style-items"
          :style="{
            width: '40%',
            'font-size': '18px',
            'font-family': selectedItem.font_style,
            'margin-left': '8px',
          }"
        >
          <div style="margin-left: 7px; margin-top: 7px">
            {{ selectedItem.font_style }}
          </div>
          <div class="text-right">
            <q-btn
              dense
              flat
              icon="expand_more"
              style="height: 39px; bottom: 34px"
            >
              <q-menu>
                <q-list style="min-width: 80px">
                  <q-item
                    v-for="font in fontlist"
                    :key="font"
                    clickable
                    v-close-popup
                  >
                    <q-item-section
                      @click="selectedItem.font_style = font"
                      :style="{ 'font-family': font }"
                      >{{ font }}</q-item-section
                    >
                  </q-item>
                </q-list>
              </q-menu>
            </q-btn>
          </div>
        </div>
        <div
          class="row style-items"
          :style="{ width: '15%', 'font-size': '17px', 'margin-left': '5px' }"
        >
          <div style="margin-left: 7px; margin-top: 7px">
            {{ selectedItem.font_size + 'pt' }}
          </div>
          <q-btn dense flat icon="expand_more" style="left: 8px; height: 39px">
            <q-menu>
              <q-list class="q-pr-sm" dense>
                <q-item
                  v-for="size in fontSizes"
                  :key="size"
                  clickable
                  v-close-popup
                >
                  <q-item-section
                    @click="selectedItem.font_size = size.value"
                    >{{ size.label }}</q-item-section
                  >
                </q-item>
              </q-list>
            </q-menu>
          </q-btn>
        </div>
        <div style="margin-left: 5px" class="style-items">
          <q-btn
            flat
            dense
            style="height: 38px"
            @click="selectedItem.bold = !selectedItem.bold"
          >
            <q-icon
              style="margin-top: 2px"
              size="32px"
              :class="selectedItem.bold == true ? 'text-primary' : 'icon-grey'"
              name="format_bold"
            />
          </q-btn>
          <q-btn
            flat
            dense
            style="height: 38px"
            @click="selectedItem.italic = !selectedItem.italic"
          >
            <q-icon
              style="margin-top: 2px"
              size="32px"
              :class="
                selectedItem.italic == true ? 'text-primary' : 'icon-grey'
              "
              name="format_italic"
            />
          </q-btn>
        </div>
        <div style="margin-left: 5px">
          <q-input
            style="width: 130px"
            outlined
            dense
            standout
            v-model="selectedItem.font_color"
            :rules="['hexColor']"
            :label="$t('annotation_color')"
          >
            <template v-slot:append>
              <q-icon
                name="colorize"
                class="cursor-pointer"
                :color="{ 'background-color': selectedItem.font_color }"
              >
                <q-popup-proxy transition-show="scale" transition-hide="scale">
                  <q-color
                    v-model="selectedItem.font_color"
                    default-view="palette"
                    no-header-tabs
                  />
                </q-popup-proxy>
              </q-icon>
            </template>
          </q-input>
        </div>
      </div>
      <q-separator style="margin-top: -14px" inset />
      <div class="q-pa-md q-gutter-sm">
        <q-input
          outlined
          type="textarea"
          autofocus
          v-model="selectedItem.text"
          :label="$t('input')"
          :input-class="
            (selectedItem.italic ? ' text-italic ' : '') +
            (selectedItem.bold ? ' text-bold ' : '')
          "
          :input-style="{
            color: selectedItem.font_color,
            fontSize: selectedItem.font_size + 'pt',
            fontFamily: selectedItem.font_style,
            lineHeight: selectedItem.font_size + 'pt',
          }"
        />
      </div>
      <q-card-actions align="right" style="margin-right: 10px">
        <q-btn
          unelevated
          :label="$t('cancel')"
          class="highlighted-back"
          @click="cancelEditorChange()"
        />
        <q-btn
          unelevated
          :label="$t('save')"
          color="primary"
          @click="saveEditorChanges"
        />
      </q-card-actions>
    </q-card>
  </q-dialog>
</template>
<script lang="ts">
// @ts-nocheck
import { notify } from 'src/components/notifications/notify';

import { storeToRefs } from 'pinia';
import { SessionStorage } from 'quasar';
import helperUtil from 'src/utils/helperUtil';
import { $, type dynamicObj } from 'src/pages/assets';
import Resizable from 'src/components/Resizable.vue';
import { defineComponent, ref, computed } from 'vue';
import { ApiExceptions } from 'src/exceptions/index';
import { documentDetailApiService } from 'src/services';
import { approval_stamp } from 'src/constants';
import { isObjectEmtpy, isUndefinedOrNull } from 'src/utils/general';
import { useDocAttributesStore, useDocumentStore } from 'src/store/main';
import {
  stamp_dir,
  stamp_ext,
} from 'src/pages/ValidationScreen/components/Annotation/helper.js';
import {
  geStamptDimension as geStamptDimensionPure,
  hexToRGB as hexToRGBPure,
  textLines as textLinesPure,
} from 'src/pages/ValidationScreen/components/Annotation/annotation-utils';
import { getUserDetailFromkey } from 'src/utils/UserDetails';
import dateUtils from 'src/utils/date';
let imageArea: HTMLElement;
let screenshot: HTMLElement;

export default defineComponent({
  setup() {
    const doc_store = useDocumentStore();
    const { page, doc_annotations } = storeToRefs(doc_store);
    const { getDocAnnotations } = doc_store;
    const ItemSelectedIndex = ref<number>(-1);
    const doc_attribute_store = useDocAttributesStore();
    const { model } = storeToRefs(doc_attribute_store);
    return {
      model,
      approval_stamp,
      getDocAnnotations,
      doc_annotations,
      page,
      fontlist: ['Helvetica', 'Times New Roman'],
      fontSizes: ref([] as dynamicObj[]),
      selectedItem: ref({} as any),
      ItemSelectedIndex,
      areas: ref([] as dynamicObj),
      ItemFormat: ref([] as any),
      approved_stamp_: 'approved_stamp_',
    };
  },
  data() {
    const dialogArea = ref({} as any);
    const dialogPos = ref({
      x: 0,
      y: 0,
    });
     
    const dialogStyle = computed(
      () =>
        `transform: translate(${dialogPos.value.x}px, ${dialogPos.value.y}px); width:${dialogArea.value.width}px; height:${dialogArea.value.height}px;`,
    );

    return {
      stamp_dir,
      stamp_ext,
      mousedown: false, // state mouse down event
      originImgSize: {
        // root size image
        w: 0,
        h: 0,
        r: 0,
      },
      url: this.cropUrl,
      posImg: {
        // position box image in screen
        top: 0,
        left: 0,
      },
      latestAreaItem: { startX: 0, startY: 0, endX: 0, endY: 0 },
      scrollLeft: 0,
      scrollTop: 0,
      moveTempX: 0,
      moveTempY: 0,
      moveCurrentX: 0,
      moveCurrentY: 0,
      temp: 0,
      dragdown: false, // state mouse event drag,
      move: false,
      imageHeight: 0,
      imageWidth: 0,

      show_annotation_popup: false,
      annotation_confirmation: false,
      dialogArea: dialogArea,
      dialogPos: dialogPos,
      dialogStyle: dialogStyle,
      fontSize: '12',
      fontStyle: 'Helvetica',
      backgroundColor: 'ffffff',
    };
  },
  mixins: [helperUtil, dateUtils],
  props: {
    cropUrl: {
      type: String,
      // default: 'https://scontent.fhan2-3.fna.fbcdn.net/v/t1.0-9/45585072_925043081015026_6599956628924006400_o.jpg?_nc_cat=108&_nc_oc=AQlJUcFj4S_wGeX016thVhmgINU5wDV4xPBNSCIcYSti9Sm5WEPBDYO_kxK4aRP0Emo&_nc_ht=scontent.fhan2-3.fna&oh=052bb05956a1460d014205754da5a15b&oe=5DCC1053'
      default:
        'https://dev.doc2api.cloudintegration.eu/resource/image/1b90b6d5-63b5-446b-92a4-a60d57dc0edd/1.png',
    },
    width: {
      type: Number,
      default: 1500,
    },
    opacityOutline: {
      type: Number,
      default: 0.2,
    },
    opacityOverlay: {
      type: Number,
      default: 0.2,
    },
    posCorrection: {
      type: Boolean,
      default: false,
    },
    selectFont: {
      type: String,
      default: 'Helvetica',
    },
    selectFontSize: {
      type: Number,
      default: 12,
    },
    selectColor: {
      type: String,
      default: '#000000',
    },
    screenmode: {
      type: String,
      default: 'annotate',
    },
    enableEditing: {
      type: Boolean,
      default: true,
    },
  },
  components: {
    Resizable,
    
  },
  watch: {
    cropUrl(val) {
      this.url = val;
      setTimeout(() => {
        this.setSize();
      }, 200);
    },
    width(val, old) {
      this.setSize();
      setTimeout(() => {
        // as the image width takes time to set in dom hence the delay
        this.prepareImageData();
      }, 0);
    },
    page(val, old) {
      this.initKnownAnnotations();
    },
  },
  methods: {
    calculateLeftForEditArea(item: dynamicObj) {
      let left = this.areaDisplayPosX(item) + item.width - 120 - item.width / 2;

      if (item.type === 'stamp') {
        left = this.areaDisplayPosX(item) + item.width - 50 - item.width / 2;
      }

      return left;
    },

    areaDisplayPosX(area: any): any {
      let left = area.x + (this.posCorrection ? this.posImg.left : 0);
      if (left <= 0) {
        left = 10;
      }
      return left;
    },
    areaDisplayPosY(area: any): any {
      return area.y + (this.posCorrection ? this.posImg.top : 0);
    },
    areaDisplayLowerPosY(area: any): any {
      return area.y + area.height;
    },
    mousePosX(e: any) {
      return e.pageX - this.posImg.left;
    },
    mousePosY(e: any) {
      return e.pageY - this.posImg.top;
    },
    setSize() {
      if (!this.url) {
        return;
      }
      // let imgSize : any = await this.getSize(this.url);
      imageArea = $('#image_area') as HTMLElement;
      this.originImgSize = {
        w: imageArea.offsetWidth,
        h: imageArea.offsetHeight,
        r: imageArea.offsetWidth / imageArea.offsetHeight,
      };
    },
    calcPosOfBox() {
      // set posImg static
      let imageAreaRef: any = this.$refs['image-area'];

      this.scrollLeft =
        window.pageXOffset || document.documentElement.scrollLeft;
      this.scrollTop = window.pageYOffset || document.documentElement.scrollTop;

      let imageAreaTop = imageAreaRef.getBoundingClientRect().top;
      let imageAreaLeft = imageAreaRef.getBoundingClientRect().left;

      this.posImg.top = imageAreaTop + this.scrollTop;
      this.posImg.left = imageAreaLeft + this.scrollLeft;
    },

    getNewAreaid() {
      let newAreaId = 1;
      if (this.areas.length > 0) {
        newAreaId = this.areas.length + 1;
      }
      return newAreaId;
    },

    // draw rectangle on image mouseDown mouseMove mouseUp
    mouseDown(e: any) {
      if (!this.enableEditing) {
        return;
      }
      this.mousedown = true;
      let newAreaId = this.getNewAreaid();
      let x = 0;
      let y = 0;
      let width = 0;
      let height = 0;

      if (this.latestAreaItem.startX != 0 && this.latestAreaItem.startY != 0) {
        let startX = this.latestAreaItem.startX;
        let startY = this.latestAreaItem.startY;

        let endX = e.pageX;
        let endY = e.pageY;

        let width = endX - startX;
        let height = endY - startY;
        if (width < 0 || height < 0) {
          endX = startX;
          endY = startY;

          startX = e.pageX;
          startY = e.pageY;

          width = endX - startX;
          height = endY - startY;
        }

        x = startX;
        y = startY;

        const newArea = this.creatReactangle(x, y, width, height, {});
        if (newArea.hasOwnProperty('id')) {
          this.temp = newArea.id;
        }

        this.latestAreaItem = { startX: 0, startY: 0, endX: 0, endY: 0 };
        return;
      }

      if (newAreaId) {
        x = this.mousePosX(e);
        y = this.mousePosY(e);

        const newArea = this.creatReactangle(x, y, width, height, {});
        if (newArea.hasOwnProperty('id')) {
          this.temp = newArea.id;
        }

        this.latestAreaItem.startX = x;
        this.latestAreaItem.startY = y;
        this.latestAreaItem.endX = width;
        this.latestAreaItem.endY = height;
      }
    },

    mouseMove(e: any) {
      if (this.mousedown) {
        this.areas
          .filter((x: dynamicObj) => x.id === this.temp)
          .map((item: dynamicObj) => {
            item.width = e.pageX - item.x - this.posImg.left - 8;
            item.height = e.pageY - item.y - this.posImg.top - 8;
          });
        this.latestAreaItem = { startX: 0, startY: 0, endX: 0, endY: 0 };
      }
    },

    mouseUp() {
      this.mousedown = false;
      // delete all point width is = 0
      this.areas = this.areas.filter(
        (item: dynamicObj) => item.width >= 3 && item.height >= 3,
      );
      this.saveEditorChangesToArea();
      this.endMove();
      this.endDrag();
      this.prepareTableArea();
    },

    // after click rectangle area select active resizable and dragable
    changeResizable(id: any) {
      this.areas
        .filter((item: dynamicObj) => item.id === id)
        .map((item: dynamicObj) => {
          item.resizable = true;
          item.z = 100;
        });
      this.areas
        .filter((item: dynamicObj) => item.id !== id)
        .map((item: dynamicObj) => {
          item.resizable = false;
          item.z = 0;
        });
    },

    async deleteAnnotation(index: number, item: dynamicObj) {
      try {
        if (isUndefinedOrNull(item.annot_id)) {
          this.areas = this.areas.filter((x: dynamicObj) => x.id !== item.id);
          return;
        }

        const response: any = await documentDetailApiService.deleteAnnotation(
          item.annot_id,
        );
        if (response.success == false) {
          throw response;
        }

        this.areas = this.areas.filter((x: dynamicObj) => x.id !== item.id);
        this.doc_annotations = this.doc_annotations.filter((x: dynamicObj) => {
          return x.id !== item.annot_id;
        });

        notify.success(this.$t('delete_success'));
      } catch (err) {
        notify.error(this.$t('delete_error'));
      }
    },

    // drag point around rectangle on image startDrag doDrag endDrag
    startDrag() {
      this.dragdown = true;
    },

    doDrag(item: any, type: any, e: any) {
      if (this.dragdown) {
        switch (type) {
          case 'w':
            // fix drag outside box w position
            if (e.pageX - this.posImg.left >= 0) {
              item.width = item.width + item.x - e.pageX + this.posImg.left;
              item.x = e.pageX - this.posImg.left;
            }
            // fix minimum area
            if (item.width < 10) {
              item.x = item.x - 10;
              item.width = item.width + 10;
            }
            break;
          case 'sw':
            // fix drag outside box sw position
            if (e.pageX - this.posImg.left >= 0) {
              item.width = item.width + item.x - e.pageX + this.posImg.left;
              item.x = e.pageX - this.posImg.left;
            }
            if (e.pageY - this.posImg.top <= this.originImgSize.h) {
              item.height = e.pageY - this.posImg.top - item.y;
            }
            // fix minimum area
            if (item.width < 10) {
              item.x = item.x - 10;
              item.width = item.width + 10;
            }
            if (item.height < 10) {
              item.height = item.height + 10;
            }
            break;
          case 's':
            // fix drag outside box s position
            if (e.pageY - this.posImg.top <= this.originImgSize.h) {
              item.height = e.pageY - this.posImg.top - item.y;
            }
            // fix minimum area
            if (item.height < 10) {
              item.height = item.height + 10;
            }
            break;
          case 'se':
            // fix drag outside box se position
            if (e.pageX - this.posImg.left <= this.originImgSize.w) {
              item.width = e.pageX - this.posImg.left - item.x;
            }
            if (e.pageY - this.posImg.top <= this.originImgSize.h) {
              item.height = e.pageY - this.posImg.top - item.y;
            }
            // fix minimum area
            if (item.width < 10) {
              item.x = item.x - 10;
              item.width = item.width + 10;
            }
            if (item.height < 10) {
              item.height = item.height + 10;
            }
            break;
          case 'e':
            // fix drag outside box e position
            if (e.pageX - this.posImg.left <= this.originImgSize.w) {
              item.width = e.pageX - this.posImg.left - item.x;
            }
            // fix minimum area
            if (item.width < 10) {
              item.x = item.x - 10;
              item.width = item.width + 10;
            }
            break;
          case 'ne':
            // fix drag outside box ne position
            if (e.pageX - this.posImg.left <= this.originImgSize.w) {
              item.width = e.pageX - this.posImg.left - item.x;
            }
            if (e.pageY - this.posImg.top >= 0) {
              item.height = item.height + (item.y + this.posImg.top - e.pageY);
              item.y = e.pageY - this.posImg.top;
            }
            // fix minimum area
            if (item.width < 10) {
              item.x = item.x - 10;
              item.width = item.width + 10;
            }
            if (item.height < 10) {
              item.height = item.height + 10;
            }
            break;
          case 'n':
            // fix drag outside box n position
            if (e.pageY - this.posImg.top >= 0) {
              item.height = item.height + (item.y + this.posImg.top - e.pageY);
              item.y = e.pageY - this.posImg.top;
            }
            // fix minimum area
            if (item.height < 10) {
              item.height = item.height + 10;
            }
            break;
          case 'nw':
            // fix drag outside box nw position
            if (e.pageY - this.posImg.top >= 0) {
              item.height = item.height + (item.y + this.posImg.top - e.pageY);
              item.y = e.pageY - this.posImg.top;
            }
            if (e.pageX - this.posImg.left >= 0) {
              item.width = item.width + item.x - e.pageX + this.posImg.left;
              item.x = e.pageX - this.posImg.left;
            }
            // fix minimum area
            if (item.width < 10) {
              item.x = item.x - 10;
              item.width = item.width + 10;
            }
            if (item.height < 10) {
              item.height = item.height + 10;
            }
            break;
          default:
            break;
        }
      }
    },

    endDrag() {
      this.dragdown = false;
    },

    // move rectangle area startMove doMove endMove
    startMove(item: any, e: any) {
      if (!this.enableEditing) {
        return;
      }
      this.move = true;
      this.moveTempX = e.clientX;
      this.moveTempY = e.clientY;
      this.moveCurrentX = item.x;
      this.moveCurrentY = item.y;
    },

    doMove(item: any, e: any) {
      if (this.move) {
        let x = this.moveCurrentX + (e.clientX - this.moveTempX);
        let y = this.moveCurrentY + (e.clientY - this.moveTempY);
        let maxX = this.originImgSize.w - item.width;
        let maxY = this.originImgSize.h - item.height;
        if (x > 0 && y > 0 && x < maxX && y < maxY) {
          item.x = x;
          item.y = y;
        }
      }
    },

    getTableAreaAsString(
      startX: number,
      startY: number,
      endX: number,
      endY: number,
    ): dynamicObj {
      let x1 = startX / this.imageWidth;
      let x2 = endX / this.imageWidth;
      let y1 = startY / this.imageHeight;
      let y2 = endY / this.imageHeight;

      return { x1, y1, x2, y2 } as dynamicObj;
    },

    prepareTableArea() {
      const areaData = [] as dynamicObj;
      this.areas.forEach((data: any) => {
        let endX = data.width + data.x;
        let endY = data.height + data.y;

        data.coordinates = this.getTableAreaAsString(
          data.x,
          data.y,
          endX,
          endY,
        );
        areaData.push(data);
      });
      SessionStorage.set('annotation_data', JSON.stringify(areaData));
    },

    endMove() {
      this.move = false;
    },

    creatReactangle(
      x: number,
      y: number,
      width: number,
      height: number,
      annoDef: dynamicObj,
    ): dynamicObj {
      const newAreaId = this.getNewAreaid();

      if (!newAreaId) {
        return {} as dynamicObj;
      }
      let editable = true;
      let type = 'normal';
      let italic = false;
      let bold = false;
      let font_size = this.fontSize;
      let font_style = this.fontStyle;
      let annot_id = null;

      if (!annoDef['text']) {
        annoDef['text'] = '';
      }

      if (annoDef['text'].includes('_stamp')) {
        type = 'stamp';
        editable = false;
      }

      if (!annoDef['font_color']) {
        annoDef['font_color'] = this.$q.dark.isActive ? '#FFFFFF' : '#000000';
      }

      if (annoDef['italic']) {
        italic = annoDef['italic'];
      }

      if (annoDef['bold']) {
        bold = annoDef['bold'];
      }

      if (annoDef['font_size']) {
        font_size = annoDef['font_size'];
      }

      if (annoDef['font_style']) {
        font_style = annoDef['font_style'];
      }

      if (annoDef['annot_id']) {
        annot_id = annoDef['annot_id'];
      }

      let firstChar = annoDef['font_color'].charAt(0);
      if (firstChar != '#') {
        annoDef['font_color'] = '#' + annoDef['font_color'];
      }

      let newArea = {
        id: newAreaId,
        annot_id: annot_id,
        x,
        y,
        width,
        height,
        z: 0,
        text: annoDef['text'],
        resizable: false,
        annoDef,
        type,
        processing: false,
        editable,
        font_style,
        font_size: font_size,
        font_color: annoDef['font_color'],
        italic,
        bold,
      };
      this.areas.push(newArea);
      return newArea as dynamicObj;
    },

    initKnownAnnotations() {
      this.areas = [];

      if (this.doc_annotations.length == 0) {
        return;
      }

      // if(SessionStorage.has('annotation_data')
      //  && SessionStorage.getItem('annotation_data') != null
      //  && SessionStorage.getItem('annotation_data') != '') {
      //   let tableDataStr = SessionStorage.getItem('annotation_data');
      //   let tableData = [] as dynamicObj[];
      //   tableData = JSON.parse(tableDataStr as string);

      //   if (tableData.length > 0) {
      //     this.doc_annotations = tableData
      //   }
      //   this.doc_annotations.forEach((annotation: any, index: number) => {
      //     this.doc_annotations[index]['x1'] = annotation.coordinates.x1;
      //     this.doc_annotations[index]['y1'] = annotation.coordinates.y1;
      //     this.doc_annotations[index]['x2'] = annotation.coordinates.x2;
      //     this.doc_annotations[index]['y2'] = annotation.coordinates.y2;
      //   });
      // }

      for (let [key, annotation] of Object.entries(this.doc_annotations)) {
        if (annotation.page != this.page - 1) {
          continue;
        }

        let startX = Math.round(this.imageWidth * annotation['x1']);
        let startY = Math.round(this.imageHeight * annotation['y1']);

        let endX = Math.round(this.imageWidth * annotation['x2']);
        let endY = Math.round(this.imageHeight * annotation['y2']);

        let width = endX - startX;
        let height = endY - startY;

        annotation['annot_id'] = annotation['id'];

        const newArea = this.creatReactangle(
          startX,
          startY,
          width,
          height,
          annotation,
        );
        if (newArea.hasOwnProperty('id')) {
          this.addAnnotationInfo(annotation, newArea.id);
        }
      }
    },

    async addAnnotationInfo(annotation: any, areaId: any) {
      if (!annotation['text'].includes('_stamp_')) {
        return;
      }

      let image_name = annotation['text'];
      if (!image_name || image_name == '') {
        return;
      }

      const res = await fetch(this.stamp_dir + image_name + this.stamp_ext);
      const data = await res.text();
      const created_item = $('#annotation_item_' + areaId) as HTMLElement;
      if (created_item) {
        created_item.innerHTML = data;
      }
    },

    hexToRGB(hex: string) {
      return hexToRGBPure(hex);
    },

    prepareImageData() {
      screenshot = $('#screenshot2') as HTMLElement;
      if (screenshot) {
        this.imageWidth = screenshot.offsetWidth;
        this.imageHeight = screenshot.offsetHeight;
      }
      this.setSize();
      setTimeout(() => this.initKnownAnnotations(), 100);
    },

    calculateLeftPosition(item: any): string {
      let left = this.areaDisplayPosX(item) + item.width;
      if (left + 50 >= this.imageWidth) {
        left = this.areaDisplayPosX(item) - 60;
      }
      return left + 'px';
    },

    calculatePositionFromTop(item: any): string {
      let top = this.areaDisplayPosY(item) - 25;
      if (top < 0) {
        top = this.areaDisplayPosY(item);
      }
      return top + 'px';
    },

    setAsSelectedItem(item: dynamicObj) {
      this.selectedItem = JSON.parse(JSON.stringify(item));
    },

    itemClicked(index: number, item: dynamicObj) {
      if (item.editable == false) {
        return;
      }
      this.ItemSelectedIndex = index;
      this.setAsSelectedItem(item);
      this.show_annotation_popup = true;
    },

    saveEditorChangesToArea() {
      if (
        isObjectEmtpy(this.selectedItem) ||
        isUndefinedOrNull(this.selectedItem)
      ) {
        return;
      }

      let index = this.areas.findIndex(
        (item: dynamicObj) => item.id === this.selectedItem.id,
      );
      this.areas[index] = this.selectedItem;
    },

    saveEditorChanges() {
      this.show_annotation_popup = false;
      this.saveEditorChangesToArea();
      this.saveAnnotation(this.ItemSelectedIndex, this.selectedItem);
    },

    // when cancel editor change set null item selected
    cancelEditorChange() {
      this.selectedItem = {};
      this.show_annotation_popup = false;
    },
    saveAnnotation(index: number, item: dynamicObj) {
      this.areas[index].processing = true;
      if (item.type === 'normal') {
        this.saveTextAnnotation(index, item);
      } else {
        this.saveStampAnnotation(index, item);
      }
    },

    getCoordinatesFromArea(item: dynamicObj) {
      let endX = item.width + item.x;
      let endY = item.height + item.y;
      return this.getTableAreaAsString(item.x, item.y, endX, endY);
    },

    async saveTextAnnotation(index: number, item: dynamicObj) {
      this.saveEditorChangesToArea();

      if (item.annot_id == null) {
        await this.addTextToDocument(index, item);
        return;
      }
      await this.editTextAnnotation(index, item);
    },

    async addTextToDocument(index: number, item: dynamicObj) {
      try {
        const rgb = this.hexToRGB(item.font_color).replace('rgb', '');
        const { x1, y1, x2, y2 } = this.getCoordinatesFromArea(item);

        let annotation: dynamicObj = {
          text: item.text,
          x1,
          y1,
          x2,
          y2,
          rgb,
          font_style: item.font_style,
          italic: item.italic,
          bold: item.bold,
          font_size: parseInt(item.font_size).toString(),
          page: this.page - 1,
          background_color: this.backgroundColor,
        };

        let doc_id = this.$route.params.id as string;
        let response: any =
          await documentDetailApiService.addAnnotateToDocument(
            doc_id,
            annotation,
          );
        if (response.success !== true) {
          throw response;
        }
        const record = response.data as dynamicObj;
        this.areas[index].annot_id = record.id;
        this.doc_annotations.push(record);

        notify.success(this.$t('save_success'));
      } catch (error) {
        const msg = ApiExceptions.getErrorMessage(error as dynamicObj);
        notify.error(msg);
        logError(error);
      } finally {
        this.areas[index].processing = false;
      }
    },

    async editTextAnnotation(index: number, item: dynamicObj) {
      try {
        const rgb = this.hexToRGB(item.font_color).replace('rgb', '');
        const { x1, y1, x2, y2 } = this.getCoordinatesFromArea(item);
        const old_annot_id = item.annot_id;

        let annotation: dynamicObj = {
          text: item.text,
          x1,
          y1,
          x2,
          y2,
          rgb,
          font_style: item.font_style,
          italic: item.italic,
          bold: item.bold,
          font_size: parseInt(item.font_size).toString(),
          page: this.page - 1,
          background_color: this.backgroundColor,
        };
        let response: any = await documentDetailApiService.editAnnotation(
          item.annot_id,
          annotation,
        );
        if (response.success !== true) {
          throw response;
        }

        const record = response.data as dynamicObj;
        if (record.hasOwnProperty('id') && record.id != undefined) {
          this.areas[index].annot_id = record.id;

          let doc_annotation_index =
            this.getIndexFromSavedAnnotations(old_annot_id);
          if (doc_annotation_index != -1) {
            this.doc_annotations[doc_annotation_index] = record;
          }
        }

        notify.success(this.$t('save_success'));
      } catch (error) {
        const msg = ApiExceptions.getErrorMessage(error as dynamicObj);
        notify.error(msg);
        logError(error);
      } finally {
        this.areas[index].processing = false;
      }
    },

    getIndexFromSavedAnnotations(annot_id: any) {
      let index = this.doc_annotations.findIndex((item: dynamicObj) => {
        return item.id == annot_id;
      });
      return index as number;
    },

    async saveStampAnnotation(index: number, item: dynamicObj) {
      if (item.annot_id == null) {
        await this.addStampToDocument(index, item);
        return;
      }

      await this.editStampAnnotation(index, item);
    },

    async editStampAnnotation(index: number, item: dynamicObj) {
      try {
        const { x1, y1, x2, y2 } = this.getCoordinatesFromArea(item);
        let annotation: dynamicObj = {
          id: this.areas[index].annot_id,
          name: item.text,
          x1,
          y1,
          x2,
          y2,
          page: this.page - 1,
        };

        let doc_id = this.$route.params.id as string;
        let response: any = await documentDetailApiService.editStampOnDocument(
          doc_id,
          annotation,
        );
        if (response.success == false) {
          throw response;
        }

        const record = response.data as dynamicObj;
        if (!this.areas[index] || !record) {
          return;
        }
        this.areas[index].annot_id = record.id;
        let doc_annotation_index = this.getIndexFromSavedAnnotations(
          this.areas[index].annot_id,
        );
        if (doc_annotation_index != -1) {
          this.doc_annotations[doc_annotation_index] = record;
        }
        notify.success(this.$t('save_success'));
      } catch (error) {
        const msg = ApiExceptions.getErrorMessage(error as dynamicObj);
        notify.error(msg);
        logError(error);
      } finally {
        if (this.areas[index]) {
          this.areas[index].processing = false;
        }
      }
    },

    async addStampToDocument(index: number, item: dynamicObj) {
      const { x1, y1, x2, y2 } = this.getCoordinatesFromArea(item);

      let annotation: dynamicObj = {
        name: item.text,
        x1,
        y1,
        x2,
        y2,
        page: this.page - 1,
      };

      try {
        let doc_id = this.$route.params.id as string;
        let response: any = await documentDetailApiService.addStampToDocument(
          doc_id,
          annotation,
        );
        if (response.success !== true) {
          notify.error(this.$t('save_error'));
        }

        const record = response.data as dynamicObj;
        if (!this.areas[index] || !record) {
          return;
        }
        this.areas[index].annot_id = record.id;
        this.doc_annotations.push(record);
        notify.success(this.$t('save_success'));
      } catch (error) {
        const msg = ApiExceptions.getErrorMessage(error as dynamicObj);
        notify.error(msg);
        logError(error);
      } finally {
        setTimeout(() => {
          if (this.areas[index]) {
            this.areas[index].processing = false;
          }
        }, 750);
      }
    },
    async addStampDescription(
      x: any,
      y: any,
      color: any,
      text: any,
      stampDef: any,
    ) {
      let def = {
        font_color: color,
      };
      const newArea = this.creatReactangle(x, y, 300, 60, def);
      const index = newArea.id - 1;
      this.areas[index]['text'] = text;
      this.areas[index]['bold'] = true;
      const texts = JSON.parse(JSON.stringify(this.areas[index]));
      await this.saveTextAnnotation(index, texts);
    },
    async addStampAnnotation(type: any) {
      const user_name =
        getUserDetailFromkey('first_name') +
        ' ' +
        getUserDetailFromkey('last_name');
      const now = new Date().toString();
      const now_format = this.formatDateAccordingToPreference(now);
      const text = `${user_name}\n${now_format}`;

      if (this.model[approval_stamp]) {
        let def = {
          text: type,
        };
        let screenshot = this.$refs.screenshot2 as HTMLLIElement;
        if (screenshot) {
          const imageWidth = screenshot.offsetWidth;
          const imageHeight = screenshot.offsetHeight;
          this.initKnownAnnotations();
          const existStamp = this.areas.filter(
            (area: any) =>
              area.text.startsWith(this.approved_stamp_) as boolean,
          );
          if (existStamp.length > 0) {
            return;
          } else {
            const stamp = this.creatReactangle(
              imageWidth - 350,
              imageHeight - 150,
              300,
              40,
              def,
            );
            this.addAnnotationInfo(stamp, stamp.id);
            const autoStamp = this.areas.filter(
              (area: any) =>
                area.text.startsWith(this.approved_stamp_) as boolean,
            );
            // guard: bail out if the stamp was not created or areas[0] is not that stamp
            if (autoStamp.length === 0 || this.areas[0] !== autoStamp[0]) {
              return;
            }
            //await for stamp to finished the saving process
            await this.saveStampAnnotation(0, autoStamp[0]);
            //add description to pdf file
            await this.addStampDescription(
              imageWidth - 350,
              imageHeight - 100,
              '#000000',
              text,
              def,
            );
          }
        }
      }
    },
    addTemplateAnnotation(type: any) {
      let def = {
        text: type,
      };
      const newArea = this.creatReactangle(100, 100, 450, 110, def);
      this.addAnnotationInfo(newArea, newArea.id);
    },

    createAnnotationFromColorShortcut(color: any) {
      let def = {
        font_color: color,
      };
      const x = this.isMobile() ? 50 : 100;
      const width = this.isMobile() ? 200 : 450;
      const newArea = this.creatReactangle(x, 100, width, 110, def);
      const index = newArea.id - 1;
      this.itemClicked(index, this.areas[index]);
    },

    onPan(evt: any) {
      this.dialogPos.x = this.dialogPos.x + evt.delta.x;
      this.dialogPos.y = this.dialogPos.y + evt.delta.y;
    },

    colorConverter(color: any) {
      let colorhex = '#';
      color = color.replace('rgb(', '').replace(')', '');
      let colorlist: [] = color.split(',');
      colorlist.forEach((colorpart: string) => {
        let part = parseInt(colorpart).toString(16);
        colorhex += part;
      });
      return colorhex;
    },

    windowResize() {
      this.setSize();
    },

    textLines(item: any): any {
      return textLinesPure(item);
    },
    geStamptDimension(stampDimension: number) {
      return geStamptDimensionPure(stampDimension, this.width);
    },
  },
  mounted() {
    this.areas = [];
    this.setSize();
    imageArea = $('#image_area') as HTMLElement;

    imageArea.addEventListener('mousemove', this.calcPosOfBox);
    imageArea.addEventListener('scroll', this.calcPosOfBox);
    this.calcPosOfBox();
    imageArea.addEventListener('mouseup', this.mouseUp);
    window.addEventListener('resize', this.windowResize);

    for (let x = 1; x <= 80; x++) {
      this.fontSizes.push({
        label: x.toString() + 'pt',
        value: x.toString(),
      });
    }
    //   (this.$refs.screenshot2 as HTMLElement).addEventListener('load', () => {
    //   this.addStampAnnotation('approved_stamp_de');
    // });
  },
  unmounted: function () {
    imageArea.removeEventListener('mousemove', this.calcPosOfBox);
    imageArea.removeEventListener('scroll', this.calcPosOfBox);
    imageArea.removeEventListener('mouseup', this.mouseUp);
    window.removeEventListener('resize', this.windowResize);
  },
});
</script>
